{
  "name": "add_app_reg_entry",
  "description": "Add a row to one of the app-registration tables \u2014 used to set up what an app does on registration (auto-assign profile/role, grant file paths, grant cross-app access, etc.).\n\nEndpoint: POST /api/security/applications/reg/{appCode}/{kind}\n\nBody shape varies by kind. Required common fields: `clientId`, `appId`, `clientType` ('BUS' or 'IND'), `level` (CLIENT/CUSTOMER/CONSUMER), `businessType` (default 'COMMON').\n\nPer-kind extras (top-level in body):\n  \u2022 userProfile      \u2192 `profileId`\n  \u2022 userRole         \u2192 `roleId`\n  \u2022 fileAccess       \u2192 `resourceType` (STATIC|SECURED), `accessName`, `writeAccess` (bool), `path` (string), `allowSubPathAccess` (bool)\n  \u2022 appAccess        \u2192 `allowAppId`, `writeAccess`, `register` (bool \u2014 can register users into the target app)\n  \u2022 department       \u2192 `name`, optional `parentDepartmentId`\n  \u2022 designation      \u2192 `name`, optional parent/next/department ids\n  \u2022 userDesignation  \u2192 `designationId`\n  \u2022 profileRestriction \u2192 `profileId`, restriction fields\n\nPrefer `configure_app_for_customer_signup` for the standard customer-signup set; this raw tool is for unusual shapes.",
  "input_schema": {
    "type": "object",
    "properties": {
      "app_code": {
        "type": "string",
        "description": "Target appCode"
      },
      "kind": {
        "type": "string",
        "description": "One of ('userProfile', 'userRole', 'fileAccess', 'appAccess', 'department', 'designation', 'userDesignation', 'profileRestriction')"
      },
      "body": {
        "type": "object",
        "description": "Full registration record body \u2014 see description for per-kind fields"
      }
    },
    "required": [
      "app_code",
      "kind",
      "body"
    ]
  }
}
